  W("perhaps","/pəˈhæps/",AD,"можливо","Perhaps we will go to the beach.","Можливо, ми підемо на пляж."),
  W("surely","/ˈʃɔːli/",AD,"напевно","It's surely going to rain.","Напевно, піде дощ."),
  W("promise","/ˈprɒmɪs/",V,"обіцяти","I promise to call.","Обіцяю зателефонувати."),
