 ("When are you going to travel?","Повторимо. Наступними вихідними. Що відповісти?",["Next weekend.","In next weekend.","On the next of weekend."],"Next weekend."),
 [("I'm definitely going to come.","Прослухайте. Що каже людина?",["Вона точно прийде","Вона можливо прийде","Вона не прийде"],"Definitely."),
  ("Perhaps we will go to the beach.","Прослухайте. Що каже людина?",["Можливо, підемо на пляж","Точно підемо на пляж","Не підемо на пляж"],"Perhaps."),
  ("I promise to call.","Прослухайте. Що обіцяє людина?",["Зателефонувати","Прийти","Написати"],"Promise.")],
 [("I'm ___ going to come.",["definitely","perhaps","promise"],"Безперечно."),
  ("___ we will go to the beach.",["Perhaps","Definitely","Promise"],"Можливо."),
  ("I'm looking forward ___ the trip.",["to","at","for"],"Look forward to.")],
 ("Що означає surely?",["напевно","можливо","обіцяти"],"Surely — напевно."),
